        i+=1
print(len(songs))

songs={}
for a in artists:
    i=0
    while True:
        r=apis.spotify.search_songs(access_token=token, artist_id=a['artist_id'], page_index=i, page_limit=20)
        if not r: break
        for s in r: songs[s['song_id']]=s['title']
        i+=1
print(len(songs))

